ValidationRule.errorConditionFormula:
AND(
  OR(
    ISCHANGED(Maker_Comments__c),
    ISCHANGED(Maker_Result__c),
    ISCHANGED(Maker_Result_Date_Time__c)
  ),
  NOT(
    OR(
      Owner:Queue.Name = "UAR Maker",
      AND(
        Previous_Owner_Queue__c = "UAR Maker",
        ISCHANGED(OwnerId)
      )
    )
  )
)
